<?php
namespace App\Livewire\Admin\Leave;use App\Enums\LeaveStatus;use App\Models\Leave;use Livewire\Component;
class Show extends Component{public Leave $leave;public string $rejection_reason='';public function mount():void{$u=auth()->user();abort_unless($u->isAdmin()||$u->isHR()||$this->leave->user_id===$u->id,403);$this->leave->load(['user','approver']);}public function approve():void{abort_unless(auth()->user()->isAdmin()||auth()->user()->isHR(),403);abort_unless($this->leave->isPending(),422);$this->leave->update(['status'=>LeaveStatus::APPROVED,'approved_by'=>auth()->id(),'approved_at'=>now(),'rejection_reason'=>null]);$this->leave->refresh();}public function reject():void{abort_unless(auth()->user()->isAdmin()||auth()->user()->isHR(),403);abort_unless($this->leave->isPending(),422);$this->validate(['rejection_reason'=>['required','string','max:2000']]);$this->leave->update(['status'=>LeaveStatus::REJECTED,'approved_by'=>auth()->id(),'approved_at'=>now(),'rejection_reason'=>$this->rejection_reason]);$this->leave->refresh();}public function render(){return view('livewire.admin.leave.show')->layout('components.layouts.admin',['title'=>'Leave request']);}}
